 private Source95AcquisitionAdmission.Snapshot admissionSnapshot(){var p=client.player;return new Source95AcquisitionAdmission.Snapshot(rootClock,rootClock.currentTick(),facade,BuilderModule.ID,VeltraphBootstrap.moduleManager().get(BuilderModule.ID).orElse(null),VeltraphBootstrap.moduleManager().inputOwner().orElse(null),p,client.level,client.getConnection(),facade.isEnabled(),client.isSameThread(),p!=null&&p.isAlive()&&p.level()==client.level,client.gameMode!=null,p!=null&&client.gui.screen()==null&&p.containerMenu==p.inventoryMenu,p!=null&&p.containerMenu.getCarried().isEmpty(),p!=null&&p.onGround(),ScriptingInputLock.isActive(),ScriptingInputLock.ownerModuleId());}
