 private void admissionDiagnostic(String phase,long now){var s=admissionSnapshot();var p=client.player;var out=new LinkedHashMap<String,Object>();out.put("phase",phase);out.put("reason",admission.reason());out.put("rootTick",s.rootTick());out.put("rootClock",identity(rootClock));out.put("clockNowMillis",rootClock.nowMillis());out.put("startupLastObservedMillis",admission.lastObservedMillis());out.put("admissionWaiting",admission.waiting());out.put("admissionAdmitted",admission.admitted());out.put("policyGeneration",policy.generation());out.put("policyRevoked",policy.revoked());out.put("policyHasKeyEpochs",policy.revisionEvidenceAvailable());out.put("policyReason",policy.reason());out.put("requiredOwnerId",BuilderModule.ID);out.put("lockActive",s.lockActive());out.put("lockOwnerId",String.valueOf(s.lockOwner()));out.put("registeredSame",s.registered()==facade);out.put("inputOwnerSame",s.inputOwner()==facade);out.put("facade",identity(facade));out.put("registered",identity(s.registered()));out.put("inputOwner",identity(s.inputOwner()));out.put("enabled",s.enabled());out.put("macroState",facade.state());out.put("sameThread",s.clientThread());out.put("nativeAlive",s.alive());out.put("gameMode",s.gameMode());out.put("player",identity(s.player()));out.put("world",identity(s.world()));out.put("connection",identity(s.connection()));out.put("capturedPlayer",identity(player));out.put("capturedWorld",identity(world));out.put("capturedConnection",identity(connection));out.put("capturedPWCSame",player==null||player==s.player()&&world==s.world()&&connection==s.connection());out.put("closedInventory",s.closedInventory());out.put("cursorEmpty",s.cursorEmpty());out.put("onGround",s.onGround());out.put("menu",p==null?"null":identity(p.containerMenu));out.put("screen",identity(client.gui.screen()));out.put("menuId",p==null?-1:p.containerMenu.containerId);out.put("menuRevision",p==null?-1:p.containerMenu.getStateId());out.put("playerTick",p==null?-1:p.tickCount);out.put("pose",p==null?"null":p.position().toString());out.put("cameraEntity",identity(client.getCameraEntity()));out.put("cameraEntitySamePlayer",client.getCameraEntity()==p);out.put("cameraAuthority",identity(dev.veltraph.client.service.mc.McOwnedRotation.authority(client)));out.put("cameraAuthoritySame",dev.veltraph.client.service.mc.McOwnedRotation.authority(client)==facade);out.put("cameraEpoch",dev.veltraph.client.service.mc.McOwnedRotation.epoch(client));out.put("cameraFrameApplications",dev.veltraph.client.service.mc.McOwnedRotation.frameApplications(client));out.put("startedMillis",started);out.put("elapsedMillis",started<0?-1:now-started);out.put("timeoutMillis",binding.timeoutMillis());out.put("authorityState",authority.state());out.put("acknowledgedUnits",authority.acquired());out.put("acknowledgedSpend",authority.spent());out.put("openedCommand",opened);out.put("chatAttached",chatAttached);out.put("uiAttached",uiAttached);out.put("packetFloor",authority.floor());out.put("chatFloor",chatFloor);out.put("legState",leg==null?"none":leg.state());System.out.println("BUILDER_SOURCE95_ADMISSION "+out);}
 private boolean sameOriginalAmount(){return client.player!=null&&authority.originalAmountMatches(client.player,client.level,client.getConnection(),facade,client.player.containerMenu,client.gui.screen(),client.player.containerMenu.containerId);}
 private String id(ItemStack s){return BuiltInRegistries.ITEM.getKey(s.getItem()).toString();}
 private boolean resource(ItemStack s){if(s.isEmpty()||!id(s).equals(binding.item()))return false;if(binding.resourceComponents().equals("@vanilla"))return ItemStack.isSameItemSameComponents(s,new ItemStack(BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.parse(binding.item()))));return McMenuAccess.componentIdentity(s,client.level.registryAccess()).equals(binding.resourceComponents());}
 private int count(){int n=0;for(int i=0;i<36;i++){var s=client.player.getInventory().getItem(i);if(!s.isEmpty()&&id(s).equals(binding.item())){if(!resource(s))throw new IllegalArgumentException("Crop components differ from explicit contract");n=Math.addExact(n,s.getCount());}}return n;}
 private List<ItemStack> inventory(){var result=new ArrayList<ItemStack>();for(int i=0;i<36;i++)result.add(client.player.getInventory().getItem(i).copy());return List.copyOf(result);}
